\title{Differential Galois Structure for EML Ordinary Differential Equations}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
We develop the differential-Galois layer of the theory of linear ordinary
differential equations whose coefficients are \emph{EML functions} --- functions
built from rational functions by iterated exponentials, logarithms, and
multiplicative/algebraic combination. Working over an arbitrary differential
field $K$ with derivation $a \mapsto a'$, we prove the structural facts that
govern every Picard--Vessiot computation. First, the \textbf{field of constants}
$\C = \{x \in K : x' = 0\}$ is a subfield. Second, the constants act on solution
spaces: the solution space of $y' = ay$ is a one-dimensional $\C$-line (the ratio
of any two nonzero solutions is constant), so its Galois group embeds in
$\Gm(\C)$; and the solution set of $y'' = ay$ is a $\C$-module closed under
scaling and addition, on which the Galois group acts linearly preserving the
\textbf{Wronskian}, which we prove constant (an abstract Abel identity). Third,
via the Riccati transform $v = y'/y$ we establish the first step of the Kovacic
algorithm for $y'' = fy$ with polynomial $f$, proving a sharp \textbf{degree--parity
obstruction}: if $\deg f$ is odd, the cleared Riccati identity
$p'q - pq' + p^2 = fq^2$ has no solution with $q \neq 0$. Specializing to $f = X$
proves that \textbf{Airy's equation $y'' = xy$ has no EML solution}. All results
hold with no algebraic-closure or characteristic hypotheses.
\end{abstract}

\section{Introduction}

The question of when a differential equation can be solved ``in closed form'' is
one of the oldest in analysis. Joseph Liouville gave the first rigorous theorems
on integration in finite terms, and \'Emile Picard and Ernest Vessiot placed the
theory on a structural footing by attaching to each linear ODE a \emph{differential
Galois group} --- an algebraic group of linear transformations of the solution
space --- with solvability in elementary (Liouvillian) terms corresponding to
solvability of this group.

The prototypical non-example is \textbf{Airy's equation}
\begin{equation}
  y'' = x\,y, \label{eq:airy}
\end{equation}
introduced by G.~B.~Airy in 1838 in the study of optical caustics. Its solutions
$\mathrm{Ai}$ and $\mathrm{Bi}$ are not expressible by any finite combination of
exponentials, logarithms, algebraic functions, and their integrals; the
differential Galois group of \eqref{eq:airy} is the full $\SL_2(\mathbb{C})$,
which is not solvable.

This paper isolates and proves the algebraic skeleton of this theory for
\textbf{EML coefficients} --- functions obtained from rational functions by
\textbf{E}xponentiation, \textbf{L}ogarithm, and \textbf{M}ultiplicative/algebraic
combination --- free of analytic, algebraic-closure, or characteristic hypotheses.
We derive: the constants subfield (\S3); the constants action on first- and
second-order solution spaces, including the Wronskian as a constant of motion
(\S4--5); and the Riccati transform with the Kovacic first-step degree--parity
obstruction, culminating in the non-EML-solvability of Airy's equation (\S6).

\section{Preliminaries}

\begin{definition}[Differential field]
A \emph{differential field} is a field $K$ with an additive map $D : K \to K$,
written $Da = a'$, satisfying the Leibniz rule $(ab)' = a'b + ab'$. One derives
$(a/b)' = (a'b - ab')/b^2$ for $b \neq 0$ and $(b^{-1})' = -b'/b^2$.
\end{definition}

\begin{definition}[Logarithmic derivative]
For $y \in K^\times$, the \emph{logarithmic derivative} is $\logd y = y'/y$.
\end{definition}

\begin{definition}[EML functions, informal]
Over a base differential field $\R(x)$ ($x' = 1$), the \emph{EML functions} are
the elements of any differential field extension obtained by finitely many steps
of adjoining exponentials ($(\exp t)' = t'\exp t$), logarithms
($(\log t)' = t'/t$), and algebraic elements. The results below are stated over an
arbitrary differential field $K$ and so apply to any such extension.
\end{definition}

Throughout, $K$ is a field with a derivation; no assumption is made on
characteristic or algebraic closure. For polynomial coefficients (\S6) we
specialize to $K = \R(X)$ with polynomials $\R[X]$.

\section{The field of constants}

\begin{definition}
The \emph{constants} of $K$ are $\C = \{x \in K : x' = 0\}$.
\end{definition}

\begin{theorem}[\texttt{constantsSubfield}]
$\C$ is a subfield of $K$.
\end{theorem}
\begin{proof}
Additivity gives $0 \in \C$ and closure under sums and negation. From $1 = 1\cdot1$
and Leibniz, $1' = 2\cdot 1'$, so $1' = 0$ and $1 \in \C$; if $a' = b' = 0$ then
$(ab)' = a'b + ab' = 0$. If $a' = 0$, $a \neq 0$, then $(a^{-1})' = -a'/a^2 = 0$.
\end{proof}

\begin{lemma}[\texttt{mem\_constantsSubfield}]
For $x \in K$, $x \in \C \iff x' = 0$.
\end{lemma}

The constants subfield is the exact base over which the differential Galois group
is a linear-algebraic group.

\section{First-order equations}

Consider $y' = a\,y$.

\begin{theorem}[\texttt{firstOrder\_ratio\_isConstant}]
If $y_1' = ay_1$, $y_2' = ay_2$, and $y_2 \neq 0$, then $(y_1/y_2)' = 0$.
\end{theorem}
\begin{proof}
$(y_1/y_2)' = (y_1'y_2 - y_1y_2')/y_2^2 = ((ay_1)y_2 - y_1(ay_2))/y_2^2 = 0$.
\end{proof}

Thus the solution space is a one-dimensional $\C$-line, and the Galois group
embeds in $\Gm(\C) = (\C^\times,\times)$, the prototypical abelian EML group. The
hypothesis $y_2 \neq 0$ is load-bearing.

\section{Second-order equations and the Wronskian}

Consider $y'' = a\,y$.

\begin{theorem}[\texttt{scale\_solution}]
If $c' = 0$ and $y'' = ay$, then $(cy)'' = a(cy)$.
\end{theorem}
\begin{proof}
$(cy)' = cy'$ and $(cy)'' = (cy')' = cy'' = c(ay) = a(cy)$.
\end{proof}

\begin{theorem}[\texttt{add\_solution}]
If $y_1'' = ay_1$ and $y_2'' = ay_2$, then $(y_1+y_2)'' = a(y_1+y_2)$.
\end{theorem}
\begin{proof}
$(y_1+y_2)'' = y_1'' + y_2'' = ay_1 + ay_2 = a(y_1+y_2)$.
\end{proof}

\begin{corollary}
The solution set $\{y : y'' = ay\}$ is a $\C$-module on which the Galois group acts
$\C$-linearly.
\end{corollary}

\begin{definition}
The \emph{Wronskian} of $y_1, y_2$ is $W(y_1,y_2) = y_1y_2' - y_2y_1'$.
\end{definition}

\begin{theorem}[\texttt{wronskian\_dependent\_eq\_zero}]
For $c' = 0$, $W(y_1, cy_1) = y_1(cy_1)' - (cy_1)y_1' = 0$.
\end{theorem}
\begin{proof}
$(cy_1)' = cy_1'$, so the expression is $cy_1y_1' - cy_1y_1' = 0$.
\end{proof}

\begin{theorem}[\texttt{wronskian\_isConstant}, via \texttt{wronskian\_deriv\_eq\_zero}]
If $y_1'' = ay_1$ and $y_2'' = ay_2$, then $W(y_1,y_2) \in \C$.
\end{theorem}
\begin{proof}
$W' = (y_1'y_2' + y_1y_2'') - (y_2'y_1' + y_2y_1'') = y_1(ay_2) - y_2(ay_1) = 0$.
\end{proof}

Hence the Galois group preserves a constant determinant: it embeds in $\SL_2(\C)$
up to a scalar. Two solutions are $\C$-independent iff their Wronskian is a nonzero
constant.

\section{The Riccati transform and the Kovacic obstruction}

\begin{theorem}[\texttt{logDeriv\_riccati}]
For $y \in K^\times$, $(\logd y)' + (\logd y)^2 = y''/y$.
\end{theorem}
\begin{proof}
With $v = y'/y$, $v' = y''/y - (y'/y)^2 = y''/y - v^2$.
\end{proof}

\begin{theorem}[\texttt{riccati\_of\_second\_order}]
If $y \in K^\times$ solves $y'' = ay$, then $v = y'/y$ solves $v' + v^2 = a$.
\end{theorem}

\begin{lemma}[Cleared Riccati identity]
$v = p/q$ with $q \neq 0$ solves $v' + v^2 = f$ in $\R(X)$ iff
\begin{equation}
  p'q - pq' + p^2 = f\,q^2 \label{eq:cleared}
\end{equation}
holds in $\R[X]$.
\end{lemma}

\begin{lemma}[\texttt{natDegree\_wronskianLike\_le}]
For $p, q \in \R[X]$, $\deg(p'q - pq') \le \deg p + \deg q - 1$.
\end{lemma}

\begin{theorem}[\texttt{no\_rational\_solves\_riccati\_odd\_deg}]
Let $f, p, q \in \R[X]$ with $q \neq 0$ and $\deg f$ odd. Then \eqref{eq:cleared}
has no solution; equivalently $v' + v^2 = f$ has no rational solution.
\end{theorem}
\begin{proof}
The right side $fq^2$ has degree $\deg f + 2\deg q$. By the previous lemma and
$\deg(p^2) = 2\deg p$, the left side has degree at most
$\max\{2\deg p,\ \deg p + \deg q - 1\}$.

\emph{Case $\deg p \ge \deg q$.} Then $2\deg p > \deg p + \deg q - 1$, so the left
side has degree exactly $2\deg p$, forcing $2\deg p = \deg f + 2\deg q$, i.e.
$\deg f = 2(\deg p - \deg q)$ is even --- contradiction.

\emph{Case $\deg p < \deg q$.} Then the left side has degree at most $2\deg q - 2$,
while the right side has degree $\ge 1 + 2\deg q$; equality is impossible.
\end{proof}

Coprimality of $p, q$ is not required: the obstruction is purely metric.

\begin{theorem}[\texttt{no\_rational\_solves\_riccati\_airy}]
There are no $p, q \in \R[X]$ with $q \neq 0$ satisfying $p'q - pq' + p^2 = Xq^2$.
\end{theorem}
\begin{proof}
Apply the previous theorem with $f = X$; $\deg X = 1$ is odd.
\end{proof}

\begin{theorem}[\texttt{no\_poly\_solves\_airy}]
No nonzero $p \in \R[X]$ satisfies $p'' = Xp$.
\end{theorem}
\begin{proof}
For $p \neq 0$, $\deg(p'') < \deg p < 1 + \deg p = \deg(Xp)$.
\end{proof}

\begin{theorem}[\texttt{airy\_no\_poly\_and\_no\_rational\_riccati}]
Airy's equation $y'' = xy$ has neither a nonzero polynomial solution nor a rational
solution of its associated Riccati equation $v' + v^2 = x$; hence it has no EML
(Liouvillian) solution.
\end{theorem}

\section{Worked examples}

\begin{example}[Airy]
$f = X$, odd degree $\Rightarrow$ no rational Riccati solution.
\end{example}
\begin{example}[Even-degree solvable]
$f = X^2 + 1$: $v = X$ gives $v' + v^2 = 1 + X^2 = f$, with $y = e^{x^2/2}$ solving
$y'' = (x^2+1)y$. The parity test is correctly silent.
\end{example}
\begin{example}[Wronskian invariant]
For $y'' = r^2y$ with constant $r$, the basis $e^{rx}, e^{-rx}$ has Wronskian
$-2r$, a nonzero constant.
\end{example}

\section{Future directions}

\textbf{D1.} For $y'' = X^ny$, odd $n$ is always obstructed and $n=2$-shaped
coefficients can be solvable; the even $n \ge 4$ regime requires refining the
degree count by a leading-coefficient condition.

\textbf{D2.} For any $K$, the solution set of $y'' = ay$ is a
$\C$-module of rank $\le 2$, rank $2$ iff some pair has nonzero Wronskian; the
Galois group embeds in $\GL_2(\C)$ preserving the (constant) Wronskian.

\textbf{D3.} If $L/K$ shares constants and $y'' = ay$ ($a \in K$) has a rational
Riccati solution in $L$, it already has one in $K$: the logarithmic derivative is
determined up to shared constants, so no genuinely new solution is gained.

\section{Conclusion}

The differential-Galois content of linear EML equations is carried by the constants
subfield and its action: first-order ratios are constants (Galois group
$\subseteq \Gm$); second-order solutions form a $\C$-module with constant Wronskian
(Galois group $\subseteq \SL_2$ up to scalar); the Riccati transform reduces order;
and a degree--parity count rules out rational Riccati solutions for odd-degree
coefficients --- in particular Airy's equation $y'' = xy$, which has no EML
solution.

